export default JSON.parse("{\"schema\":\"ai-brain-source-note/1.0\",\"domain\":\"vtt-maps\",\"capabilities\":[\"canon\",\"crop\",\"grid\",\"layer\",\"map\",\"perspective\"],\"provenance\":{\"sourceGroup\":\"active-session-runtime-c\",\"sourceType\":\"provided-project-material\",\"archiveHash\":\"be64160633c6ca96\"},\"title\":\"grid_formats.md\",\"content\":\"# ActiveWorkspace Canonical Grid Formats\\n\\nAll encounter maps are expected to use one of the supplied grid overlays or a tiled/resized derivative of them. ActiveWorkspace treats every square as **5 ft \u00d7 5 ft**, regardless of source resolution.\\n\\n| Source grid | Image size | Grid squares | Source pixels per square |\\n|---|---:|---:|---:|\\n| `Grid (17x22).png` | 5100 \u00d7 6600 | 34 \u00d7 44 | 150 \u00d7 150 |\\n| `Grid (22x17).png` | 3300 \u00d7 2550 | 22 \u00d7 17 | 150 \u00d7 150 |\\n| `Grid (8.5x11).png` | 2550 \u00d7 3300 | 17 \u00d7 22 | 150 \u00d7 150 |\\n| `Seamless Grid Pattern (1x1).png` | 1200 \u00d7 1200 | 8 \u00d7 8 | 150 \u00d7 150 |\\n| `Seamless Grid Pattern (2x2).png` | 2400 \u00d7 2400 | 16 \u00d7 16 | 150 \u00d7 150 |\\n| `Seamless Grid Pattern (3x3).png` | 3600 \u00d7 3600 | 24 \u00d7 24 | 150 \u00d7 150 |\\n\\n## Detection behavior\\n\\n1. Exact source dimensions use an immediate canonical profile match.\\n2. Maps tiled from the supplied 150-pixel pattern are snapped to the same family after line verification.\\n3. Resized or composited maps use alpha-aware and luminance-aware periodic line scanning.\\n4. Transparent black grid overlays are detected from their alpha channel rather than incorrectly read as solid black images.\\n5. Cropped maps retain detected origin and grid bounds.\\n6. Manual rows and columns remain available for perspective-distorted or heavily obscured maps.\\n\\nThe runtime profile registry is in `json/canonical_grid_profiles.json`. The source references are in `assets/grids/canonical/`.\\n\"}");
